<template><BaseModal v-model="visible" size="md" :close-disabled="loading" :close-on-esc="!loading" :close-on-overlay-click="!loading"><template #header><div class="title"><h2>{{ingredient?'ویرایش قیمت ماده اولیه':'ماده اولیه جدید'}}</h2><p v-if="ingredient">{{ingredient.name}}</p></div></template><form id="ingredient-form" dir="rtl" novalidate @submit.prevent="submit"><div v-if="serverError" class="error" role="alert">{{serverError}}</div><div class="grid"><label class="wide">نام ماده اولیه <b>الزامی</b><input ref="nameInput" v-model.trim="form.name" maxlength="100" placeholder="مثلاً شیر"/><em v-if="errors.name">{{errors.name}}</em></label><label>واحد اندازه‌گیری <b>الزامی</b><select v-model="form.unit"><option v-for="unit in units" :key="unit[0]" :value="unit[0]">{{unit[1]}}</option></select><em v-if="errors.unit">{{errors.unit}}</em></label><label>قیمت خرید هر واحد <b>تومان · الزامی</b><input v-model="form.purchase_price" type="number" min="0.01" step="0.01" inputmode="decimal"/><small v-if="form.purchase_price">{{Number(form.purchase_price).toLocaleString('fa-IR')}} تومان برای هر {{unitLabel}}</small><em v-if="errors.purchase_price">{{errors.purchase_price}}</em></label><label class="active wide"><span><strong>ماده اولیه فعال باشد</strong><small>فقط مواد فعال در دستور تولید قابل انتخاب‌اند.</small></span><input v-model="form.is_active" type="checkbox"/></label></div></form><template #footer><button class="secondary" :disabled="loading" @click="visible=false">انصراف</button><button class="primary" form="ingredient-form" :disabled="loading">{{loading?'در حال ذخیره…':ingredient?'ذخیره تغییرات':'ایجاد ماده اولیه'}}</button></template></BaseModal></template>
<script setup>import{computed,nextTick,reactive,ref,watch}from'vue';import BaseModal from'@/components/modals/BaseModal.vue';const props=defineProps({modelValue:Boolean,ingredient:{type:Object,default:null},units:{type:Array,default:()=>[]},loading:Boolean,serverError:{type:String,default:''},fieldErrors:{type:Object,default:()=>({})}}),emit=defineEmits(['update:modelValue','submit']),visible=computed({get:()=>props.modelValue,set:value=>emit('update:modelValue',value)}),form=reactive({name:'',unit:'g',purchase_price:'',is_active:true}),errors=reactive({}),nameInput=ref(null),unitLabel=computed(()=>props.units.find(item=>item[0]===form.unit)?.[1]||'واحد');function clear(){Object.keys(errors).forEach(key=>delete errors[key])}function hydrate(){clear();Object.assign(form,{name:props.ingredient?.name||'',unit:props.ingredient?.unit||props.units[0]?.[0]||'g',purchase_price:props.ingredient?.purchase_price||'',is_active:props.ingredient?.is_active??true});if(props.modelValue)nextTick(()=>nameInput.value?.focus())}function submit(){clear();if(!form.name)errors.name='نام ماده اولیه را وارد کنید.';if(!form.unit)errors.unit='واحد را انتخاب کنید.';if(!form.purchase_price||Number(form.purchase_price)<=0)errors.purchase_price='قیمت باید بزرگ‌تر از صفر باشد.';if(!Object.keys(errors).length)emit('submit',{...form,purchase_price:Number(form.purchase_price)})}watch(()=>[props.modelValue,props.ingredient,props.units],hydrate,{immediate:true,deep:true});watch(()=>props.fieldErrors,value=>{clear();for(const[key,messages]of Object.entries(value||{}))errors[key]=Array.isArray(messages)?messages[0]:messages},{deep:true})</script>
<style scoped>.title h2,.title p{margin:0}.title h2{font-size:1.15rem}.title p{margin-top:3px;color:var(--muted);font-size:.72rem}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.wide{grid-column:1/-1}label{display:grid;gap:6px;font-size:.78rem;font-weight:700}label>b{color:var(--muted);font-size:.64rem;font-weight:400}input,select{width:100%;min-height:43px;padding:9px 11px;border:1px solid var(--border-strong);border-radius:9px;background:var(--input);color:var(--text);font:inherit;box-sizing:border-box}input:focus,select:focus{outline:3px solid var(--focus);border-color:var(--primary)}label small{color:var(--muted);font-size:.65rem;font-weight:400}em{color:var(--danger);font-size:.7rem;font-style:normal}.active{display:flex;align-items:center;justify-content:space-between;padding:12px;border:1px solid var(--border);border-radius:9px}.active span{display:grid;gap:3px}.active input{width:20px;min-height:20px;accent-color:var(--primary)}.error{margin-bottom:14px;padding:10px;border:1px solid #fecaca;border-radius:8px;background:#fef2f2;color:var(--danger);font-size:.74rem}.primary,.secondary{min-width:110px;padding:10px 14px;border:0;border-radius:9px;font:inherit;font-weight:700}.primary{background:var(--primary);color:#fff}.secondary{background:var(--surface-subtle);color:var(--text)}@media(max-width:600px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
